1. Build the GitHub API endpoint for listing a user’s repositories.
2. Fetch all repository pages from the API (following pagination via the `Link` header).
3. Parse each response body as JSON and collect `(created_at, name)` pairs.
4. Sort the collected repositories by their creation timestamp from oldest to newest.
5. Return the sorted list of repository names; if any request fails or the response is invalid, return an empty list.

### code
```python
import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        return []

    url = API_URL.rstrip('/') + '/' + user + '/repos'
    params = {'per_page': 100, 'page': 1}
    repos = []

    while True:
        try:
            resp = requests.get(url, params=params, headers={'Accept': 'application/vnd.github+json'}, timeout=20)
        except requests.RequestException:
            return []

        if resp.status_code != 200:
            return []

        try:
            payload = json.loads(resp.text)
        except Exception:
            return []

        if not isinstance(payload, list):
            return []

        for r in payload:
            if isinstance(r, dict):
                name = r.get('name')
                created_at = r.get('created_at')
                if isinstance(name, str) and isinstance(created_at, str):
                    repos.append((created_at, name))

        link = resp.headers.get('Link', '')
        if 'rel="next"' in link:
            params['page'] += 1
            continue
        break

    repos.sort(key=lambda x: x[0])
    return [name for _, name in repos]
