2. Recursively search the parsed content to find a candidate IP address.
3. Validate the candidate using the IPv4 regex and numeric octet bounds, and ensure it is a public address.
4. Return the valid IP address, or the required invalid message if validation fails.

### code
```python
import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

INVALID_MESSAGE = 'Invalid IP address received'

def _find_ip(obj):
    if isinstance(obj, str):
        match = re.search(IP_REGEX, obj)
        return match.group(0) if match else None
    if isinstance(obj, dict):
        for key in ('ip', 'ip_address', 'public_ip', 'address', 'data'):
            if key in obj:
                found = _find_ip(obj[key])
                if found:
                    return found
        for value in obj.values():
            found = _find_ip(value)
            if found:
                return found
    if isinstance(obj, list):
        for item in obj:
            found = _find_ip(item)
            if found:
                return found
    return None

def _is_public_ipv4(ip):
    if not re.fullmatch(IP_REGEX, ip):
        return False
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    try:
        octets = [int(p) for p in parts]
    except ValueError:
        return False
    if any(p < 0 or p > 255 for p in octets):
        return False
    a, b, c, d = octets
    if (
        a == 0
        or a == 10
        or a == 127
        or (a == 169 and b == 254)
        or (a == 172 and 16 <= b <= 31)
        or (a == 192 and b == 168)
        or (a == 100 and 64 <= b <= 127)
        or (a == 198 and b in (18, 19))
        or 224 <= a <= 239
        or a >= 240
    ):
        return False
    return True

def task_func(ip_address):
    try:
        parsed = json.loads(ip_address)
    except (TypeError, json.JSONDecodeError):
        parsed = ip_address
    ip = _find_ip(parsed)
    if ip and _is_public_ipv4(ip):
        return ip
    return INVALID_MESSAGE
```

