from collections import Counter
def task_func(json_dir_path, word_count):
    if not os.path.isdir(json_dir_path) or word_count is None:
        return []

    re = __import__('re')

    counter = Counter()

    for filename in os.listdir(json_dir_path):
        if not filename.endswith('.json'):
