# Constants
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []

    if isinstance(input_data, (dict, list)):
        data = input_data
    else:
        try:
            data = json.loads(input_data)
        except (json.JSONDecodeError, TypeError):
            return []

    recipient_emails = []
    names = []

    def add_email(value):
        if isinstance(value, str):
            v = value.strip()
            if v and v not in recipient_emails:
                recipient_emails.append(v)
        elif isinstance(value, list):
            for item in value:
                add_email(item)

    def add_name(value):
        if isinstance(value, str):
            v = value.strip()
            if v:
                names.append(v)
        elif isinstance(value, list):
            for item in value:
                add_name(item)

    if isinstance(data, dict):
        for k in ("email", "to", "recipient_email", "recipient"):
            if k in data:
                add_email(data.get(k))

        if "name" in data:
            add_name(data.get("name"))
        if "names" in data:
            add_name(data.get("names"))

        recs = data.get("recipients")
        if isinstance(recs, list):
            for r in recs:
                if isinstance(r, dict):
                    if "email" in r:
                        add_email(r.get("email"))
                    if "name" in r:
                        add_name(r.get("name"))
                elif isinstance(r, str):
                    add_email(r)

    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                if "email" in item:
                    add_email(item.get("email"))
                if "to" in item:
                    add_email(item.get("to"))
                if "recipient_email" in item:
                    add_email(item.get("recipient_email"))
                if "recipient" in item:
                    add_email(item.get("recipient"))
                if "name" in item:
                    add_name(item.get("name"))
                if "names" in item:
                    add_name(item.get("names"))
                if "recipients" in item and isinstance(item.get("recipients"), list):
                    for r in item.get("recipients"):
                        if isinstance(r, dict):
                            if "email" in r:
                                add_email(r.get("email"))
                            if "name" in r:
                                add_name(r.get("name"))
                        elif isinstance(r, str):
                            add_email(r)

    msg = "Subject: Extracted Names\n\n" + "\n".join(names)

    if recipient_emails:
        created = False
        server = smtp
        if server is None:
            server = smtplib.SMTP(smtp_server, smtp_port)
            created = True
        try:
            if created:
                server.ehlo()
                server.starttls()
                server.ehlo()
                server.login(email_address, email_password)
            server.sendmail(email_address, recipient_emails, msg)
        finally:
            if created:
                try:
                    server.quit()
                except Exception:
                    pass

    return names
