```python
import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    try:
        with open(file_path, "r") as f:
            data = json.load(f)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON file")
    except OSError:
        raise ValueError("File does not exist")
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")
    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])
    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")
    for field, rules in properties.items():
        if field in data:
            expected_type = rules.get("type")
            if expected_type is not None and not isinstance(data[field], expected_type):
                raise ValueError(f"Type mismatch for attribute: {field}")
            if field == "email" and re.fullmatch(EMAIL_REGEX, data[field]) is None:
                raise ValueError("Invalid email format")
    if attribute not in properties:
        raise ValueError("Attribute not defined in schema")
    if attribute not in data:
        raise ValueError(f"Missing attribute: {attribute}")
    return data[attribute]
