                collected[k].append(float(v))

    keys = sorted(set(collected.keys()) | {k for d in data if isinstance(d, dict) for k in d.keys()})

    rows = {}
    for k in keys:
        vals = collected.get(k, [])
        if len(vals) == 0:
            rows[k] = {"mean": np.nan, "median": np.nan}
        else:
            arr = np.array(vals, dtype=float)
            rows[k] = {"mean": float(np.mean(arr)), "median": float(np.median(arr))}

    df = pd.DataFrame.from_dict(rows, orient="index")[["mean", "median"]]
    df = df.sort_index()
    return df
