1. Parse the input JSON string into a Python object and ensure it is a flat dictionary; otherwise return an empty DataFrame.
2. Normalize each key’s value by doubling numeric content:
   - If the value is a number, multiply by 2.
   - If the value is a list of numbers, multiply each element by 2.
   - If the value is a string, extract all numeric substrings via regex, convert to floats, and double them (single number becomes a scalar; multiple numbers become a list); if no numbers are found, keep the original string.
3. Build a Pandas DataFrame from the normalized dictionary:
   - If any values are lists, construct a columnar DataFrame and broadcast scalar values to the maximum list length.
   - Otherwise, construct a single-row DataFrame.
4. Ensure numeric outputs are stored as floats, and return the resulting DataFrame (or an empty one if nothing valid can be converted).

### code
```python
import json
import re
import pandas as pd
def task_func(json_str):
    if json_str is None or (isinstance(json_str, str) and json_str.strip() == ""):
        return pd.DataFrame()

    try:
        obj = json.loads(json_str)
    except Exception:
        return pd.DataFrame()

    if not isinstance(obj, dict) or len(obj) == 0:
        return pd.DataFrame()

    num_pat = re.compile(r'[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?')

    def normalize_value(v):
        if isinstance(v, bool) or v is None:
            return v
        if isinstance(v, (int, float)):
            return float(v) * 2.0
        if isinstance(v, list):
            out = []
            ok = True
            for x in v:
                if isinstance(x, bool) or x is None:
                    ok = False
                    break
                if isinstance(x, (int, float)):
                    out.append(float(x) * 2.0)
                elif isinstance(x, str):
                    found = num_pat.findall(x)
                    if len(found) != 1:
                        ok = False
                        break
                    out.append(float(found[0]) * 2.0)
                else:
                    ok = False
                    break
            return out if ok else v
        if isinstance(v, str):
            found = num_pat.findall(v)
            if not found:
                return v
            nums = [float(x) * 2.0 for x in found]
            return nums[0] if len(nums) == 1 else nums
        return v

    normalized = {k: normalize_value(v) for k, v in obj.items()}
    if len(normalized) == 0:
        return pd.DataFrame()

    list_lengths = [len(v) for v in normalized.values() if isinstance(v, list)]
    if list_lengths:
        n = max(list_lengths) if list_lengths else 0
        if n == 0:
            return pd.DataFrame()

        cols = {}
        for k, v in normalized.items():
            if isinstance(v, list):
                if len(v) == n:
                    cols[k] = v
                elif len(v) == 1:
                    cols[k] = [v[0]] * n
                else:
                    cols[k] = v + [pd.NA] * (n - len(v))
            else:
                cols[k] = [v] * n
        return pd.DataFrame(cols)

    return pd.DataFrame([normalized])
```

