```python
import json
from glob import glob
import os

def task_func(directory, string):
    def contains_string(obj, target):
        if isinstance(obj, str):
            return obj == target
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(k, str) and k == target:
                    return True
                if contains_string(v, target):
                    return True
            return False
        if isinstance(obj, list):
            for item in obj:
                if contains_string(item, target):
                    return True
            return False
        return False

    pattern = os.path.join(directory, "**", "*.json")
    files = glob(pattern, recursive=True)

    matched = []
    for path in files:
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue

        if contains_string(data, string):
            matched.append(path)

    return matched
```

