import json
import numpy as np
COLUMNS = ['email', 'list']
def task_func(json_file):
    import matplotlib.pyplot as plt

    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError, TypeError):
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None

    if isinstance(data, dict):
        if 'email' in data and 'list' in data:
            records = [data]
        else:
            records = []
    elif isinstance(data, list):
        records = [d for d in data if isinstance(d, dict) and 'email' in d and 'list' in d]
    else:
        records = []

    if not records:
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None

    df = pd.DataFrame(records)
    if 'email' not in df.columns:
        df['email'] = None
    if 'list' not in df.columns:
        df['list'] = [[] for _ in range(len(df))]
    df = df[['email', 'list']]

    def calc_sum(x):
        if isinstance(x, (list, tuple, np.ndarray)) and len(x) > 0:
            return float(np.sum(x))
        if isinstance(x, (list, tuple, np.ndarray)) and len(x) == 0:
            return 0.0
        return 0.0

    def calc_mean(x):
        if isinstance(x, (list, tuple, np.ndarray)) and len(x) > 0:
            return float(np.mean(x))
        if isinstance(x, (list, tuple, np.ndarray)) and len(x) == 0:
            return float('nan')
        return float('nan')

